INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11343', '0', 'admin', 'system', 'INSERT', 'questions', '537', NULL, '{\"text\": \"6. Prepare the environment, ensure adequate lighting, ventilation, and privacy ? mark\", \"score_values\": \"0, 0.25, 0.5\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11344', '0', 'admin', 'system', 'INSERT', 'questions', '538', NULL, '{\"text\": \"7. Position the patient in a high Fowler?s or sitting position, with head flexed slightly forward to prevent entry into the trachea. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11345', '0', 'admin', 'system', 'INSERT', 'questions', '539', NULL, '{\"text\": \"8. Protect the patient?s clothing with a towel or a mackintosh. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11346', '0', 'admin', 'system', 'INSERT', 'questions', '540', NULL, '{\"text\": \"9. Inspect the nostrils for patency and select the more patent nostril for insertion. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11347', '0', 'admin', 'system', 'INSERT', 'questions', '541', NULL, '{\"text\": \"10. Measure the length of the tube to be inserted, from the tip of the nose to the ear lobe, then to the xiphoid process, and mark it with adhesive tape or a pen. 2 marks\", \"score_values\": \"0, 1, 2\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11348', '0', 'admin', 'system', 'INSERT', 'questions', '542', NULL, '{\"text\": \"12. Lubricate the distal 10?15 cm of the tube with water-soluble jelly to ease insertion. 1Mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11349', '0', 'admin', 'system', 'INSERT', 'questions', '543', NULL, '{\"text\": \"13. Gently insert the tube along the floor of the selected nostril, directing backward and downward. 1? mark\", \"score_values\": \"0, 1, 1.5\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11350', '0', 'admin', 'system', 'INSERT', 'questions', '544', NULL, '{\"text\": \"14. When the tube reaches the oropharynx, instruct the patient to swallow as the tube advances. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11351', '0', 'admin', 'system', 'INSERT', 'questions', '545', NULL, '{\"text\": \"15. Observe patient?s response; stop immediately if coughing, choking, or cyanosis occurs (may indicate tracheal entry). Withdraw tube slightly and reattempt if safe. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11352', '0', 'admin', 'system', 'INSERT', 'questions', '546', NULL, '{\"text\": \"16. Confirm placement: aspirate gastric contents and test with litmus paper (acidic pH) or inject air and auscultate over the epigastrium for gurgling sound. 1 ? mark\", \"score_values\": \"0, 1, 1.5\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11353', '0', 'admin', 'system', 'INSERT', 'questions', '547', NULL, '{\"text\": \"17. Alternatively, immerse the tube end in water; air bubbles indicate wrong placement in the airway. 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11354', '0', 'admin', 'system', 'INSERT', 'questions', '548', NULL, '{\"text\": \"18. Once confirmed, close the distal end with a spigot and secure the tube on the nose/cheek with adhesive tape to prevent dislodgment. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:54:57');
