INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11410', '0', 'admin', 'system', 'INSERT', 'questions', '604', NULL, '{\"text\": \"Ensure  Aseptic techniques 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:58:46');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11411', '0', 'admin', 'system', 'INSERT', 'questions', '605', NULL, '{\"text\": \"Strip the top sheet by placing a bath blanket over the sheet and remove the sheet from underneath the bath blanket, then fold neatly on the bed stripper. 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:58:46');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11412', '0', 'admin', 'system', 'INSERT', 'questions', '606', NULL, '{\"text\": \"Place the second bath blanket underneath the patient. 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:58:46');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11413', '0', 'admin', 'system', 'INSERT', 'questions', '607', NULL, '{\"text\": \"Gently remove the patient?s clothing. ?mark\", \"score_values\": \"0, 0.25, 0.5\"}', '', '', '2025-10-16 10:58:46');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11414', '0', 'admin', 'system', 'INSERT', 'questions', '608', NULL, '{\"text\": \"Wash the pressure areas with soapy water, using a bath flannel, rinse thoroughly, dry, and apply barrier cream.( a. Back of the head. b. Elbows. c. Shoulders. d. Knees. e. Ankles. f. Heels. g. Buttocks   2 marks\", \"score_values\": \"0, 1, 2\"}', '', '', '2025-10-16 10:58:46');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11415', '0', 'admin', 'system', 'INSERT', 'questions', '609', NULL, '{\"text\": \"Straighten the bottom sheet and remake the bed 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:58:46');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11416', '0', 'admin', 'system', 'INSERT', 'questions', '610', NULL, '{\"text\": \"Make patient comfortable, remove screen, turn on fan, and open window 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:58:46');
