INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11419', '0', 'admin', 'system', 'INSERT', 'questions', '613', NULL, '{\"text\": \"Document the findings 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:58:46');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11420', '0', 'admin', 'system', 'INSERT', 'questions', '614', NULL, '{\"text\": \"1. Greets the patient ? mark\", \"score_values\": \"0, 0.25, 0.5\"}', '', '', '2025-10-16 10:58:59');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11421', '0', 'admin', 'system', 'INSERT', 'questions', '615', NULL, '{\"text\": \"2. Explain the procedure to the patient. ? mark\", \"score_values\": \"0, 0.25, 0.5\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11422', '0', 'admin', 'system', 'INSERT', 'questions', '616', NULL, '{\"text\": \"3. Obtain informed consent. ? mark\", \"score_values\": \"0, 0.25, 0.5\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11423', '0', 'admin', 'system', 'INSERT', 'questions', '617', NULL, '{\"text\": \"4. Assemble required equipment 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11424', '0', 'admin', 'system', 'INSERT', 'questions', '618', NULL, '{\"text\": \"5. Wash hands thoroughly using aseptic technique 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11425', '0', 'admin', 'system', 'INSERT', 'questions', '619', NULL, '{\"text\": \"6. Prepare the environment, ensure adequate lighting, ventilation, and privacy ? mark\", \"score_values\": \"0, 0.25, 0.5\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11426', '0', 'admin', 'system', 'INSERT', 'questions', '620', NULL, '{\"text\": \"7. Position the patient in a high Fowler?s or sitting position, with head flexed slightly forward to prevent entry into the trachea. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11427', '0', 'admin', 'system', 'INSERT', 'questions', '621', NULL, '{\"text\": \"8. Protect the patient?s clothing with a towel or a mackintosh. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11428', '0', 'admin', 'system', 'INSERT', 'questions', '622', NULL, '{\"text\": \"9. Inspect the nostrils for patency and select the more patent nostril for insertion. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11429', '0', 'admin', 'system', 'INSERT', 'questions', '623', NULL, '{\"text\": \"10. Measure the length of the tube to be inserted, from the tip of the nose to the ear lobe, then to the xiphoid process, and mark it with adhesive tape or a pen. 2 marks\", \"score_values\": \"0, 1, 2\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11430', '0', 'admin', 'system', 'INSERT', 'questions', '624', NULL, '{\"text\": \"12. Lubricate the distal 10?15 cm of the tube with water-soluble jelly to ease insertion. 1Mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11431', '0', 'admin', 'system', 'INSERT', 'questions', '625', NULL, '{\"text\": \"13. Gently insert the tube along the floor of the selected nostril, directing backward and downward. 1? mark\", \"score_values\": \"0, 1, 1.5\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11432', '0', 'admin', 'system', 'INSERT', 'questions', '626', NULL, '{\"text\": \"14. When the tube reaches the oropharynx, instruct the patient to swallow as the tube advances. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11433', '0', 'admin', 'system', 'INSERT', 'questions', '627', NULL, '{\"text\": \"15. Observe patient?s response; stop immediately if coughing, choking, or cyanosis occurs (may indicate tracheal entry). Withdraw tube slightly and reattempt if safe. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11434', '0', 'admin', 'system', 'INSERT', 'questions', '628', NULL, '{\"text\": \"16. Confirm placement: aspirate gastric contents and test with litmus paper (acidic pH) or inject air and auscultate over the epigastrium for gurgling sound. 1 ? mark\", \"score_values\": \"0, 1, 1.5\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11435', '0', 'admin', 'system', 'INSERT', 'questions', '629', NULL, '{\"text\": \"17. Alternatively, immerse the tube end in water; air bubbles indicate wrong placement in the airway. 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11436', '0', 'admin', 'system', 'INSERT', 'questions', '630', NULL, '{\"text\": \"18. Once confirmed, close the distal end with a spigot and secure the tube on the nose/cheek with adhesive tape to prevent dislodgment. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11437', '0', 'admin', 'system', 'INSERT', 'questions', '631', NULL, '{\"text\": \"19. Make the patient comfortable, place in semi-Fowler?s position, and clean any lubricant or secretions. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11438', '0', 'admin', 'system', 'INSERT', 'questions', '632', NULL, '{\"text\": \"20. Dispose of used items safely in appropriate waste containers, remove gloves, wash hands, and tidy the bedside. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('11439', '0', 'admin', 'system', 'INSERT', 'questions', '633', NULL, '{\"text\": \"21. Document the procedure 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2025-10-16 10:59:01');
