INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14423', '0', 'admin', 'system', 'UPDATE', 'questions', '558', '{\"text\": \"7. Position the patient in a high Fowler?s or sitting position, with head flexed slightly forward to prevent entry into the trachea. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '{\"text\": \"7. Position the patient in a high Fowler?s or sitting position, with head flexed slightly forward to prevent entry into the trachea. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2026-01-26 18:53:44');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14424', '0', 'admin', 'system', 'UPDATE', 'questions', '559', '{\"text\": \"8. Protect the patient?s clothing with a towel or a mackintosh. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '{\"text\": \"8. Protect the patient?s clothing with a towel or a mackintosh. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2026-01-26 18:53:44');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14425', '0', 'admin', 'system', 'UPDATE', 'questions', '560', '{\"text\": \"9. Inspect the nostrils for patency and select the more patent nostril for insertion. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '{\"text\": \"9. Inspect the nostrils for patency and select the more patent nostril for insertion. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2026-01-26 18:53:44');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14426', '0', 'admin', 'system', 'UPDATE', 'questions', '561', '{\"text\": \"10. Measure the length of the tube to be inserted, from the tip of the nose to the ear lobe, then to the xiphoid process, and mark it with adhesive tape or a pen. 2 marks\", \"score_values\": \"0, 1, 2\"}', '{\"text\": \"10. Measure the length of the tube to be inserted, from the tip of the nose to the ear lobe, then to the xiphoid process, and mark it with adhesive tape or a pen. 2 marks\", \"score_values\": \"0, 1, 2\"}', '', '', '2026-01-26 18:53:44');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14427', '0', 'admin', 'system', 'UPDATE', 'questions', '562', '{\"text\": \"12. Lubricate the distal 10?15 cm of the tube with water-soluble jelly to ease insertion. 1Mark\", \"score_values\": \"0, 0.5, 1\"}', '{\"text\": \"12. Lubricate the distal 10?15 cm of the tube with water-soluble jelly to ease insertion. 1Mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2026-01-26 18:53:44');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14428', '0', 'admin', 'system', 'UPDATE', 'questions', '563', '{\"text\": \"13. Gently insert the tube along the floor of the selected nostril, directing backward and downward. 1? mark\", \"score_values\": \"0, 1, 1.5\"}', '{\"text\": \"13. Gently insert the tube along the floor of the selected nostril, directing backward and downward. 1? mark\", \"score_values\": \"0, 1, 1.5\"}', '', '', '2026-01-26 18:53:44');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14429', '0', 'admin', 'system', 'UPDATE', 'questions', '564', '{\"text\": \"14. When the tube reaches the oropharynx, instruct the patient to swallow as the tube advances. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '{\"text\": \"14. When the tube reaches the oropharynx, instruct the patient to swallow as the tube advances. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2026-01-26 18:53:44');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('14430', '0', 'admin', 'system', 'UPDATE', 'questions', '565', '{\"text\": \"15. Observe patient?s response; stop immediately if coughing, choking, or cyanosis occurs (may indicate tracheal entry). Withdraw tube slightly and reattempt if safe. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '{\"text\": \"15. Observe patient?s response; stop immediately if coughing, choking, or cyanosis occurs (may indicate tracheal entry). Withdraw tube slightly and reattempt if safe. 1 mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2026-01-26 18:53:44');
