INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('22663', '0', 'admin', 'system', 'UPDATE', 'questions', '849', '{\"text\": \"Fontanelles ?are soft sports where two  or more sutures meets. There are two:  i) anterior fontanelles or bregma, is diamond in shape, situated at the junction of the sagittal, coronal and frontal sutures. It closes at 18 months. 1mark\", \"score_values\": \"0, 0.5, 1\"}', '{\"text\": \"Fontanelles are soft sports where two  or more sutures meets. There are two:  i) anterior fontanelles or bregma, is diamond in shape, situated at the junction of the sagittal, coronal and frontal sutures. It closes at 18 months. 1mark\", \"score_values\": \"0, 0.5, 1\"}', '', '', '2026-03-02 18:44:14');
