INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24446', '0', 'admin', 'system', 'INSERT', 'questions', '895', NULL, '{\"text\": \"Gently remove the old dressing (using adhesive remover if necessary). Observe for drainage, odor, and color. 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:33');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24447', '0', 'admin', 'system', 'INSERT', 'questions', '896', NULL, '{\"text\": \"Skin Inspection 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:00:33');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24448', '0', 'admin', 'system', 'INSERT', 'questions', '897', NULL, '{\"text\": \"Assess the wound for staging (size, depth, exudate, slough, granulation). Note the condition of the surrounding skin (peri wound). 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24449', '0', 'admin', 'system', 'INSERT', 'questions', '898', NULL, '{\"text\": \"Cleanse the ulcer using 0.9% Normal Saline. Use gentle, direct irrigation or moist gauze. Do not scrub. 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24450', '0', 'admin', 'system', 'INSERT', 'questions', '899', NULL, '{\"text\": \"Apply a barrier cream to surrounding skin. Reposition the patient, ensuring the wound is not under direct pressure. 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24451', '0', 'admin', 'system', 'INSERT', 'questions', '900', NULL, '{\"text\": \"Ensure the patient is comfortable. 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24452', '0', 'admin', 'system', 'INSERT', 'questions', '901', NULL, '{\"text\": \"Turn patient every 2hours 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24453', '0', 'admin', 'system', 'INSERT', 'questions', '902', NULL, '{\"text\": \"Wash your hand and remove glove 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24454', '0', 'admin', 'system', 'INSERT', 'questions', '903', NULL, '{\"text\": \"Tidy your environment 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24455', '0', 'admin', 'system', 'INSERT', 'questions', '904', NULL, '{\"text\": \"Make Patient comfortable 1/2\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-03-04 11:00:34');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24456', '0', 'admin', 'system', 'INSERT', 'questions', '905', NULL, '{\"text\": \"Prepare Equipment:?Assemble linen (2 sheets, blanket, bedspread, pillowcase, mackintosh/drawsheet) on a clean trolley/chair in order of use. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24457', '0', 'admin', 'system', 'INSERT', 'questions', '906', NULL, '{\"text\": \"Hand Hygiene & PPE:?Perform hand hygiene; put on gloves if handling soiled linen. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24458', '0', 'admin', 'system', 'INSERT', 'questions', '907', NULL, '{\"text\": \"Position Bed:?Raise bed to a comfortable working height (waist level) and lock wheels. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24459', '0', 'admin', 'system', 'INSERT', 'questions', '908', NULL, '{\"text\": \"Remove Soiled Linen:?Loosen old linen, remove, and roll inwards (soiled side inside). Place in hamper; do not shake or let it touch your uniform. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24460', '0', 'admin', 'system', 'INSERT', 'questions', '909', NULL, '{\"text\": \"Clean Mattress:?If necessary, wipe mattress with disinfectant an1d allow to dry. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24461', '0', 'admin', 'system', 'INSERT', 'questions', '910', NULL, '{\"text\": \"Draw Sheet:?Place in the middle of the bed (under patient\'s back/hips) and tuck on both sides. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24462', '0', 'admin', 'system', 'INSERT', 'questions', '911', NULL, '{\"text\": \"Apply Top Linen:?Spread top sheet blanket, and spread. Tuck at the foot of the bed and miter corners. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24463', '0', 'admin', 'system', 'INSERT', 'questions', '912', NULL, '{\"text\": \"Pillow & Finish:?Apply pillowcase. Place pillow with open end away from the door. 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('24464', '0', 'admin', 'system', 'INSERT', 'questions', '913', NULL, '{\"text\": \"Lower the bed and ock its wheels to ensure patient safety 1\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-03-04 11:01:27');
