INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32581', '0', 'admin', 'system', 'INSERT', 'questions', '972', NULL, '{\"text\": \"2. Explain the procedure to the patient. ? mark\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32582', '0', 'admin', 'system', 'INSERT', 'questions', '973', NULL, '{\"text\": \"3. Obtain informed consent. ? mark\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32583', '0', 'admin', 'system', 'INSERT', 'questions', '974', NULL, '{\"text\": \"4. Assemble required equipment 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32584', '0', 'admin', 'system', 'INSERT', 'questions', '975', NULL, '{\"text\": \"5. Wash hands thoroughly using aseptic technique 1mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32585', '0', 'admin', 'system', 'INSERT', 'questions', '976', NULL, '{\"text\": \"6. Prepare the environment, ensure adequate lighting, ventilation, and privacy ? mark\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32586', '0', 'admin', 'system', 'INSERT', 'questions', '977', NULL, '{\"text\": \"7. Position the patient in a high Fowler?s or sitting position, with head flexed slightly forward to prevent entry into the trachea. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32587', '0', 'admin', 'system', 'INSERT', 'questions', '978', NULL, '{\"text\": \"8. Protect the patient?s clothing with a towel or a mackintosh. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32588', '0', 'admin', 'system', 'INSERT', 'questions', '979', NULL, '{\"text\": \"9. Inspect the nostrils for patency and select the more patent nostril for insertion. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32589', '0', 'admin', 'system', 'INSERT', 'questions', '980', NULL, '{\"text\": \"10. Measure the length of the tube to be inserted, from the tip of the nose to the ear lobe, then to the xiphoid process, and mark it with adhesive tape or a pen. 2 marks\", \"score_values\": \"0.5, 1,2\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32590', '0', 'admin', 'system', 'INSERT', 'questions', '981', NULL, '{\"text\": \"12. Lubricate the distal 10?15 cm of the tube with water-soluble jelly to ease insertion. 1Mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32591', '0', 'admin', 'system', 'INSERT', 'questions', '982', NULL, '{\"text\": \"13. Gently insert the tube along the floor of the selected nostril, directing backward and downward. 1? mark\", \"score_values\": \"0.5,0.75,1.5\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32592', '0', 'admin', 'system', 'INSERT', 'questions', '983', NULL, '{\"text\": \"14. When the tube reaches the oropharynx, instruct the patient to swallow as the tube advances. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32593', '0', 'admin', 'system', 'INSERT', 'questions', '984', NULL, '{\"text\": \"15. Observe patient?s response; stop immediately if coughing, choking, or cyanosis occurs (may indicate tracheal entry). Withdraw tube slightly and reattempt if safe. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32594', '0', 'admin', 'system', 'INSERT', 'questions', '985', NULL, '{\"text\": \"16. Confirm placement: aspirate gastric contents and test with litmus paper (acidic pH) or inject air and auscultate over the epigastrium for gurgling sound. 1 ? mark\", \"score_values\": \"0.5,0.75,1.5\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32595', '0', 'admin', 'system', 'INSERT', 'questions', '986', NULL, '{\"text\": \"17. Alternatively, immerse the tube end in water; air bubbles indicate wrong placement in the airway. 1mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32596', '0', 'admin', 'system', 'INSERT', 'questions', '987', NULL, '{\"text\": \"18. Once confirmed, close the distal end with a spigot and secure the tube on the nose/cheek with adhesive tape to prevent dislodgment. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
