INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32598', '0', 'admin', 'system', 'INSERT', 'questions', '989', NULL, '{\"text\": \"20. Dispose of used items safely in appropriate waste containers, remove gloves, wash hands, and tidy the bedside. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:37:05');
