INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32607', '0', 'admin', 'system', 'INSERT', 'questions', '995', NULL, '{\"text\": \"5. Wash hands thoroughly using aseptic technique 1mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32608', '0', 'admin', 'system', 'INSERT', 'questions', '996', NULL, '{\"text\": \"6. Prepare the environment, ensure adequate lighting, ventilation, and privacy ? mark\", \"score_values\": \"0,0.25,0.5\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32609', '0', 'admin', 'system', 'INSERT', 'questions', '997', NULL, '{\"text\": \"7. Position the patient in a high Fowler?s or sitting position, with head flexed slightly forward to prevent entry into the trachea. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32610', '0', 'admin', 'system', 'INSERT', 'questions', '998', NULL, '{\"text\": \"8. Protect the patient?s clothing with a towel or a mackintosh. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32611', '0', 'admin', 'system', 'INSERT', 'questions', '999', NULL, '{\"text\": \"9. Inspect the nostrils for patency and select the more patent nostril for insertion. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32612', '0', 'admin', 'system', 'INSERT', 'questions', '1000', NULL, '{\"text\": \"10. Measure the length of the tube to be inserted, from the tip of the nose to the ear lobe, then to the xiphoid process, and mark it with adhesive tape or a pen. 2 marks\", \"score_values\": \"0.5, 1,2\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32613', '0', 'admin', 'system', 'INSERT', 'questions', '1001', NULL, '{\"text\": \"12. Lubricate the distal 10?15 cm of the tube with water-soluble jelly to ease insertion. 1Mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32614', '0', 'admin', 'system', 'INSERT', 'questions', '1002', NULL, '{\"text\": \"13. Gently insert the tube along the floor of the selected nostril, directing backward and downward. 1? mark\", \"score_values\": \"0.5,0.75,1.5\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32615', '0', 'admin', 'system', 'INSERT', 'questions', '1003', NULL, '{\"text\": \"14. When the tube reaches the oropharynx, instruct the patient to swallow as the tube advances. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32616', '0', 'admin', 'system', 'INSERT', 'questions', '1004', NULL, '{\"text\": \"15. Observe patient?s response; stop immediately if coughing, choking, or cyanosis occurs (may indicate tracheal entry). Withdraw tube slightly and reattempt if safe. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32617', '0', 'admin', 'system', 'INSERT', 'questions', '1005', NULL, '{\"text\": \"16. Confirm placement: aspirate gastric contents and test with litmus paper (acidic pH) or inject air and auscultate over the epigastrium for gurgling sound. 1 ? mark\", \"score_values\": \"0.5,0.75,1.5\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32618', '0', 'admin', 'system', 'INSERT', 'questions', '1006', NULL, '{\"text\": \"17. Alternatively, immerse the tube end in water; air bubbles indicate wrong placement in the airway. 1mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
INSERT INTO `audit_trail` (`id`, `user_id`, `user_type`, `username`, `action`, `table_name`, `record_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('32619', '0', 'admin', 'system', 'INSERT', 'questions', '1007', NULL, '{\"text\": \"18. Once confirmed, close the distal end with a spigot and secure the tube on the nose/cheek with adhesive tape to prevent dislodgment. 1 mark\", \"score_values\": \"0,0.5,1\"}', '', '', '2026-04-23 09:55:49');
