INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('39', 'about_lead', 'Founded on the principle that digital education requires uncompromising security, NextGen Assessment Portal bridges the gap between remote testing and physical invigilation.');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('40', 'about_desc', 'We provide institutions with a robust framework to conduct high-stakes examinations anywhere in the world, backed by real-time neural monitoring and automated behavioral analysis.');
