INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('48', 'sec_title', 'The <span class=\"text-success\">7-Layer Security</span> Stack');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('49', 'sec_lead', 'Uncompromised academic integrity backed by active hardware-to-cloud security measures.');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('50', 'sec_l7_title', 'OS Kiosk (SEB)');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('51', 'sec_l7_desc', 'Locks the entire system at the operating system level via native Safe Exam Browser integration, completely disabling desktop swaps, background communication, or external displays.');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('52', 'sec_l6_title', 'Browser Lockdown');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('53', 'sec_l6_desc', 'Aggressive JavaScript restrictions. Intercepts and blocks F12 inspection tools, right-click context menus, Ctrl+U source printing, Alt+F4 closures, and cuts off clipboard paste capabilities.');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('54', 'sec_l5_title', 'Tab Blur Counters');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('55', 'sec_l5_desc', 'Active viewport focus monitoring. Triggers immediate audible warning sound alarms when browser focus is lost. Dynamically auto-submits assessments upon reaching the 5-strike threshold.');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('56', 'sec_l4_title', 'Webcam Proctoring');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('57', 'sec_l4_desc', 'Periodic frame-by-frame snapshot capture saved securely to archives. Provides live-feed synchronization using WebRTC so proctors can invigilate multiple rooms concurrently.');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('58', 'sec_l3_title', 'Device Whitelisting');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('59', 'sec_l3_desc', 'Centralized IP and device authorization gates. Intercepts initial handshakes, blocks unrecognized remote endpoints, and places new connections into a dynamic review queue.');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('60', 'sec_l2_title', 'Session Hardening');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`) VALUES ('61', 'sec_l2_desc', 'Rigid session control. Generates and swaps session tokens at login to neutralize hijack attacks. Multi-device tracking prevents dual-login instances, securing individual credentials.');
